$('#uploadBtn').onclick=()=>$('#bookFile').click();$('#bookFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const status=$('#uploadStatus'),book=file.name.replace(/\.(txt|md|pdf|docx|epub|fb2|html?|rtf)$/i,'').trim(),audience=$('#audience').value.trim(),platform=selectedPlatform(),cached=audience?findCachedBook(book,audience,platform):null;matchedHistoryProject=cached||null;sourceBreakdown=null;$('#sourceBreakdown').classList.add('hidden');status.textContent=`正在提取并整理文件：${file.name}…`;status.classList.remove('ready');$('#bookDetected').textContent=cached?'✓ 已匹配同书名、目标用户和平台的历史记录':`正在读取《${book}》…`;$('#bookDetected').classList.toggle('ready',!!cached);try{documentContext=await extractDocument(file);if(documentContext.trim().length<100)throw new Error('文档可提取文字过少，请检查文件内容');const info=window.trueReadRecognitionInfo||{originalChars:documentContext.length,packetCount:1,usedPacketCount:1};documentName=file.name;$('#book').value=book;$('#bookDetected').textContent=`✓ 已识别书籍：《${book}》`;$('#bookDetected').classList.add('ready');status.classList.add('ready');if(cached){status.textContent=`已上传：${file.name} · 已整理为 ${info.packetCount} 个识别包 · 已恢复与当前用户和平台匹配的 ${cached.topics.length} 个历史选题`;restoreProject(cached)}else{status.textContent=audience?`已上传：${file.name} · 已提取 ${info.originalChars.toLocaleString()} 个字符 · 已整理为 ${info.packetCount} 个识别包 · 未命中相同用户与平台的历史记录`:`已上传：${file.name} · 已提取 ${info.originalChars.toLocaleString()} 个字符 · 已整理为 ${info.packetCount} 个识别包 · 填写目标用户后才会匹配历史选题`;current=[];resetQuotes();$('#results').classList.add('hidden');showAIStatus(`文件上传成功：${file.name}${audience?'，可生成针对当前目标用户的新选题':'，请填写目标用户后生成选题'}`,'success')}}catch(err){documentContext='';documentName='';sourceBreakdown=null;matchedHistoryProject=null;window.trueReadRecognitionInfo=null;$('#book').value='';$('#bookDetected').textContent='尚未上传可读取的书籍文件';e.target.value='';status.textContent=`文件上传失败：${err.message}`;showAIStatus(`文件上传失败：${err.message}`,'error')}};
