$('#bookForm').onsubmit=async e=>{e.preventDefault();const book=$('#book').value.trim(),audience=$('#audience').value.trim(),platform=selectedPlatform();if(!documentContext||!book)return toast('请先上传书籍文件');if(!audience){matchedHistoryProject=null;return toast('请填写目标用户')}const cached=findCachedBook(book,audience,platform);if(cached){restoreProject(cached);return}matchedHistoryProject=null;const btn=e.submitter;btn.classList.add('loading');btn.disabled=true;btn.querySelector('span').textContent='正在准备选题…';let breakdownWarning='';try{if(!sourceBreakdown){try{sourceBreakdown=await analyzeBookSource(book,documentContext,documentName);renderSourceBreakdown(sourceBreakdown)}catch(err){sourceBreakdown=null;breakdownWarning=`源文档拆解失败：${err.message||'服务暂不可用'}；已跳过拆解，继续直接基于上传文件生成选题。`;showAIStatus(breakdownWarning,'warning')}}btn.querySelector('span').textContent=`正在生成${platform}内容…`;if(!breakdownWarning)showAIStatus(`生成5个选题：已完成源文档拆解，正在生成${platform}内容…`);const result=await generateFromSource(book,audience,documentContext,'document',platform,sourceBreakdown);renderAI(result,book,audience,'document',platform);$('#results').classList.remove('hidden');$('#results').scrollIntoView({behavior:'smooth'});showAIStatus(`生成5个选题成功 · ${platform} · 已针对“${audience}”生成${breakdownWarning?' · 本次未使用源文档拆解':''}`,'success')}catch(err){showAIStatus(`生成5个选题失败：${err.message||'服务暂不可用'}`,'error');toast('生成5个选题失败')}finally{btn.classList.remove('loading');btn.disabled=false;btn.querySelector('span').textContent='重新生成 5 个选题'}};
function render(book,audience){const groups=[['最关注的问题',['时间被切碎','付出缺少反馈','注意力分散','成长难坚持']],['情绪需求',['被理解','掌控感','价值感','确定性']],['付费动机',['节省整理时间','获得行动模板','陪伴监督','快速见效']]];$('#analysisTitle').textContent=`${audience}真正关心什么？`;$('#insights').innerHTML=groups.map(g=>`<article class="insight"><h3>${g[0]}</h3>${g[1].map(x=>`<span>${x}</span>`).join('')}</article>`).join('');const source=documentContext?`参考已导入的《${documentName}》材料提取观点`:`结合《${book}》中关于目标、反馈与投入的核心思路`;current=titles.slice(0,5).map((t,i)=>({id:i,title:t.replace('{人群}',audience),category:categories[i%10],score:(9.7-(i%10)*.12).toFixed(1),book,audience,pain:['付出很多但缺少反馈','碎片化休息无法恢复精力','知道方法却难行动'][i%3],insight:`${source}，正式发布前请结合原书核验具体表述。`,hook:t.replace('{人群}',audience),action:'选择一件难度适中、目标清晰的事，关闭提醒，连续投入30分钟并记录反馈。',quote:'真正消除疲惫的，不只是停下来，而是重新找回对生活的投入感。'}));resetQuotes();draw(current);const project={book,audience,documentName,time:new Date().toLocaleString(),createdAt:Date.now()};localStorage.setItem('lastProject',JSON.stringify(project));const projects=JSON.parse(localStorage.getItem('bookProjects')||'[]').filter(p=>p.book!==book);localStorage.setItem('bookProjects',JSON.stringify([project,...projects].slice(0,30)))}
function renderAI(data,book,audience,sourceType,platform){const a=data.audienceAnalysis||{};const groups=[['最关注的问题',a.mainProblems||[]],['情绪需求',a.emotionalNeeds||[]],['生活场景',a.lifeScenarios||[]],['内容偏好',a.paymentMotivations||[]]];$('#analysisTitle').textContent=`${audience}真正关心什么？`;const badge=document.createElement('span');badge.className='source-badge';badge.textContent=`${platform} · ${sourceType==='document'?'上传文档':sourceType==='web_search'?'授权网页搜索':'公开书目'}`;$('#analysisTitle').appendChild(badge);$('#insights').innerHTML=groups.map(g=>`<article class="insight"><h3>${g[0]}</h3>${g[1].map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</article>`).join('');current=(data.topics||[]).slice(0,5).map((t,i)=>({id:i,book,audience,platform,title:t.title,shortTitle:t.shortTitle||'',article:t.article||'',category:t.category||categories[i%10],score:Number(t.score||8.5).toFixed(1),pain:t.painPoint,insight:t.bookInsight,hook:t.hook,action:t.actionAdvice,quote:t.goldenSentence,sourceType}));if(current.length<5)throw new Error(`AI 仅返回 ${current.length} 个有效主题，请重试`);matchedHistoryProject=null;resetQuotes();draw(current);const project={book,audience,platform,documentName,sourceType,audienceAnalysis:a,topics:current,time:new Date().toLocaleString(),createdAt:Date.now()};saveBookProject(project)}
function draw(items){$('#topics').innerHTML=items.map(t=>`<article class="topic" data-id="${t.id}"><div class="meta"><span>${t.category}</span><b>${t.score}</b></div><h3>${t.title}</h3><p>${t.insight}</p><button class="topic-open">${t.platform==='公众号'?'查看文章':'查看文案'}</button></article>`).join('');document.querySelectorAll('.topic').forEach(e=>e.onclick=()=>openContent(current[+e.dataset.id]))}
function rankTopics(mode){if(mode==='all')return [...current];const words=mode==='easy'?/方法|行动|清单|步骤|练习|生活|职场|情绪|关系/:/变现|金钱|财富|成长|课程|社群|资料|职场|规划/;return [...current].sort((a,b)=>{const textA=`${a.category} ${a.title} ${a.action||''}`,textB=`${b.category} ${b.title} ${b.action||''}`;const rankA=(words.test(textA)?20:0)+Number(a.score||0),rankB=(words.test(textB)?20:0)+Number(b.score||0);return rankB-rankA})}
